mapper.select:
SELECT '0' AS CHK , SRVC_CD -- 고객사 , WH_CD -- 센터 , CLIENT_CD -- 거래처코드 , CLIENT_NM -- 거래터명 , BUSINESS_NO -- 사업자번호 , BSN_TYPE_NM -- 업태명 , BSN_ITEM_NM -- 종목명 , PRESIDENT_NM -- 대표자명 , PRESIDENT_HP -- 대표자연락처 , PRESIDENT_EMAIL -- 이메일주소 , ADDRESS -- 거래처주소 , NATION_CD -- 국가코드 , ZIP_CD -- 우편번호 , TEL_NO -- 전화번호 , TRADE_TYPE -- 거래유형 , USE_YN -- 사용여부 , COALESCE(NULLIF(WMS.FN_GET_USER_NM(REG_ID), ''), '') AS REG_ID -- 등록자 , TO_CHAR(REG_DATE, 'YYYY-MM-DD') AS REG_DATE -- 등록일자 , COALESCE(NULLIF(WMS.FN_GET_USER_NM(UPD_ID), ''), '') AS UPD_ID -- 수정자 , TO_CHAR(UPD_DATE, 'YYYY-MM-DD') AS UPD_DATE -- 수정일자 FROM WMS.TB_CLIENT WHERE 1 = 1 AND SRVC_CD = #{srvcCd} AND WH_CD = #{whCd}
AND CLIENT_CD LIKE '%' || #{clientCd} || '%'
AND USE_YN = #{useYn}
ORDER BY SRVC_CD, WH_CD, CLIENT_CD

mapper.insert:
MERGE INTO WMS.TB_CLIENT T
USING (
        SELECT #{srvcCd}            AS SRVC_CD
             , #{whCd}              AS WH_CD
             , #{clientCd}          AS CLIENT_CD
             , #{clientNm}          AS CLIENT_NM
             , #{businessNo}        AS BUSINESS_NO
             , #{bsnTypeNm}         AS BSN_TYPE_NM
             , #{bsnItemNm}         AS BSN_ITEM_NM
             , #{presidentNm}       AS PRESIDENT_NM
             , #{presidentEmail}    AS PRESIDENT_EMAIL
             , #{presidentHp}       AS PRESIDENT_HP
             , #{address}           AS ADDRESS
             , #{nationCd}          AS NATION_CD
             , #{zipCd}             AS ZIP_CD
             , #{tradeType}         AS TRADE_TYPE
             , #{useYn}             AS USE_YN
             , #{userId}            AS USER_ID
      ) AS S
   ON ( T.SRVC_CD = S.SRVC_CD AND T.WH_CD = S.WH_CD AND T.CLIENT_CD = S.CLIENT_CD )
 WHEN MATCHED THEN
    UPDATE 
      SET CLIENT_NM = #{clientNm}
        , BUSINESS_NO = #{businessNo}
        , ADDRESS = #{address}
        , NATION_CD = #{nationCd}
        , PRESIDENT_NM = #{presidentNm}
        , PRESIDENT_EMAIL = #{presidentEmail}
        , PRESIDENT_HP = #{presidentHp}
        , USE_YN = #{useYn}
        , BSN_ITEM_NM = #{bsnItemNm}
        , UPD_ID = #{userId}
        , UPD_DATE = NOW()
 WHEN NOT MATCHED THEN 
    INSERT (
        SRVC_CD
      , WH_CD
      , CLIENT_CD
      , CLIENT_NM
      , BUSINESS_NO
      , BSN_TYPE_NM
      , BSN_ITEM_NM
      , PRESIDENT_NM
      , PRESIDENT_EMAIL
      , PRESIDENT_HP
      , ADDRESS
      , NATION_CD
      , ZIP_CD
      , TEL_NO
      , TRADE_TYPE
      , USE_YN
      , REG_ID
      , REG_DATE
    ) VALUES (
        #{srvcCd}
      , #{whCd}
      , #{clientCd}
      , #{clientNm}
      , #{businessNo}
      , #{bsnTypeNm}
      , #{bsnItemNm}
      , #{presidentNm}
      , #{presidentEmail}
      , #{presidentHp}
      , #{address}
      , #{nationCd}
      , #{zipCd}
      , #{telNo}
      , #{tradeType}
      , #{useYn}
      , #{userId}
      , NOW()
    )

